import org.deeptimeline.app.*
import java.math.BigDecimal
import java.time.LocalDateTime
import kotlin.math.abs
fun main(){val start=Moment(0,0);check(start.shift(java.math.BigInteger.valueOf(-1))==Moment(-1,999999999));check(Moment.fromTotal(start.total())==start);val lon=TimeMath.fromLongitude(LocalDateTime.parse("1970-01-01T00:00:00"),BigDecimal("0.001"));check(lon.first==Moment(-1,760000000));check(lon.second=="240000000");check(TimeMath.fromLocal(LocalDateTime.parse("2026-03-08T02:30:00"),"America/New_York").first.isEmpty());check(TimeMath.fromLocal(LocalDateTime.parse("2026-11-01T01:30:00"),"America/New_York").first.size==2);check(Coordinates.parse("39.7392N, 104.9903W").second==BigDecimal("-104.9903"));val y=LabelSolver.solve(DoubleArray(1000){it/1000.0},25.0);for(i in 1 until y.size)check(y[i]-y[i-1]>24.999);for(v in listOf(DAY_SECONDS,MONTH_SECONDS,YEAR_SECONDS)){val spp=v/4000.0;check(abs(spp*4000.0-v)<0.00000001)};val reference=Moment(100,0);check(TimeMath.screenY(reference,reference,0.25,1000)==500.0);check(TimeMath.screenY(Moment(100,250000000),reference,0.25,1000)==501.0);check(TimeMath.screenY(Moment(99,750000000),reference,0.25,1000)==499.0);check(TimeMath.screenY(Moment(300,0),reference,0.25,1000)>1000.0);val historic=TimeMath.fromUtc(LocalDateTime.parse("1493-12-21T12:00:00"));check(historic.utc().startsWith("1493-12-21"));println("Temporal math, coordinate interpretation, DST gaps and overlaps, 1,000-label solver, 4,000-pixel scales, moving Now marker: PASS")}
